import { FieldView } from './view3d.js';
'use strict';
const {Simulation,base,W,H,hubs,BR,clamp}=FieldPhysics;
const $=id=>document.getElementById(id),sim=new Simulation(),canvas=$('field'),view=new FieldView(canvas);
let paused=false,grid=true,keys=new Set(),last=0,accumulator=0,scale=1,ox=0,oy=0,cw=0,ch=0;
const schema=[['maxSpeed','Top speed',1,6,.1,'m/s','driveSettings'],['acceleration','Acceleration',1,12,.5,'m/s²','driveSettings'],['width','Width',.55,1.2,.05,'m','driveSettings'],['length','Length',.55,1.2,.05,'m','driveSettings'],['intakeRate','Intake rate',1,15,1,'fuel/s','fuelSettings'],['feedRate','Feed rate',1,15,1,'fuel/s','fuelSettings'],['capacity','Capacity',1,80,1,'fuel','fuelSettings'],['stationary','Stationary accuracy',10,100,1,'%','shootSettings'],['moving','Moving accuracy',5,100,1,'%','shootSettings']];
const names={'341':'Miss Daisy','1640':'Sab-BOT-age','2590':'Nemesis',custom:'Your robot'};
const profiles={'341':{...base},'1640':{...base,team:'1640',maxSpeed:4.2,capacity:40,intakeRate:7,feedRate:5},'2590':{...base,team:'2590',maxSpeed:4.8,capacity:24,feedRate:8,moving:75},custom:{...base,team:'custom'}};
for(let [id,label,min,max,step,unit,group] of schema){let row=document.createElement('div');row.className='slider-row';row.innerHTML=`<label for="${id}">${label}<output id="${id}Value"></output></label><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${base[id]}">`;$(group).append(row);$(id).addEventListener('input',()=>{sim.setConfig({[id]:Number($(id).value)});refreshConfig();});}
function refreshConfig(){for(let [id,,min,max,step,unit] of schema){$(id).value=sim.config[id];$(id+'Value').textContent=(step<1?Number(sim.config[id]).toFixed(step===.05?2:1):sim.config[id])+' '+unit;}$('drive').value=sim.config.drive;$('alliance').value=sim.config.alliance;$('autoAim').checked=sim.config.autoAim;$('team').value=sim.config.team;$('robotNumber').textContent=sim.config.team==='custom'?'FMA':sim.config.team;$('robotName').textContent=names[sim.config.team];$('robotType').textContent=(sim.config.drive==='swerve'?'Swerve':'Tank')+' · '+(sim.config.alliance==='blue'?'Blue':'Red')+' alliance';document.querySelector('.mini-robot').style.borderColor=sim.config.alliance==='blue'?'#568eed':'#e16d65';}
function updateIntake(){$('intake').innerHTML=`<span>◉ Intake ${sim.intake?'enabled':'disabled'}</span><kbd>I</kbd>`;$('intake').setAttribute('aria-pressed',sim.intake);}
function togglePause(){paused=!paused;keys.clear();$('pause').textContent=paused?'▶ Resume':'Ⅱ Pause';$('stateLabel').textContent=paused?'PRACTICE PAUSED':'FREE PRACTICE';$('hint').textContent=paused?'Paused · Press P or Resume to continue':'Drive over fuel with your front intake · Hold Space to shoot';}
$('pause').onclick=togglePause;$('reset').onclick=()=>{sim.reset();keys.clear();updateIntake();};$('intake').onclick=()=>{sim.intake=!sim.intake;updateIntake();};$('viewGrid').onclick=()=>{grid=!grid;$('viewGrid').textContent=grid?'▦ Grid on':'▦ Grid off';$('viewGrid').setAttribute('aria-pressed',grid);};
$('team').onchange=()=>{sim.setConfig({...profiles[$('team').value],alliance:sim.config.alliance});sim.reset();refreshConfig();updateIntake();};$('drive').onchange=()=>{sim.setConfig({drive:$('drive').value});refreshConfig();};$('alliance').onchange=()=>{sim.setConfig({alliance:$('alliance').value});sim.reset();refreshConfig();updateIntake();};$('autoAim').onchange=()=>sim.setConfig({autoAim:$('autoAim').checked});
$('save').onclick=()=>{try{localStorage.setItem('fma-profile-v1',JSON.stringify(sim.config));$('saveStatus').textContent='Profile saved in this browser.';}catch{$('saveStatus').textContent='Storage unavailable in this browser.';}};
$('load').onclick=()=>{try{let raw=localStorage.getItem('fma-profile-v1');if(!raw){$('saveStatus').textContent='No saved profile yet.';return;}let p=JSON.parse(raw),valid={...base};for(let [id,,min,max]of schema)if(Number.isFinite(p[id]))valid[id]=clamp(p[id],min,max);valid.capacity=Math.round(valid.capacity);valid.drive=p.drive==='tank'?'tank':'swerve';valid.alliance=p.alliance==='red'?'red':'blue';valid.autoAim=p.autoAim!==false;valid.team=Object.hasOwn(names,p.team)?p.team:'custom';sim.setConfig(valid);sim.reset();refreshConfig();updateIntake();$('saveStatus').textContent='Saved profile loaded.';}catch{$('saveStatus').textContent='Could not load this profile.';}};
$('help').onclick=()=>{if(!paused)togglePause();$('helpDialog').showModal();};$('closeHelp').onclick=()=>$('helpDialog').close();
const used=['KeyW','KeyA','KeyS','KeyD','KeyQ','KeyE','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','KeyI','KeyP'];
window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName)||$('helpDialog').open)return;if(!used.includes(e.code))return;e.preventDefault();if(!e.repeat&&e.code==='KeyP')togglePause();else if(!e.repeat&&e.code==='KeyI')$('intake').click();else keys.add(e.code);});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();last=0;});canvas.addEventListener('pointerdown',()=>canvas.focus());
for(let button of document.querySelectorAll('[data-hold]')){button.onpointerdown=e=>{e.preventDefault();button.setPointerCapture(e.pointerId);keys.add(button.dataset.hold);};for(let type of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(type,()=>keys.delete(button.dataset.hold));}
new ResizeObserver(()=>view.resize()).observe(canvas);
function draw(){view.draw(sim,grid);const r=sim.robot,c=sim.config;
$('score').textContent=sim.score;$('inventory').textContent=sim.inventory;$('capacityDisplay').textContent='/ '+c.capacity;$('shots').textContent=sim.fired+' shots fired';$('accuracy').textContent=sim.resolved?Math.round(sim.score/sim.resolved*100)+'%':'—';$('speed').textContent=Math.hypot(r.vx,r.vy).toFixed(1);$('fill').style.width=sim.inventory/c.capacity*100+'%';let t=Math.floor(sim.time);$('elapsed').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')+' practice time';}
$('camera').onchange=()=>view.setCamera($('camera').value);
function frame(now){let dt=last?Math.min((now-last)/1000,.1):0;last=now;if(!paused&&!document.hidden){accumulator+=dt;while(accumulator>=1/120){sim.step(1/120,{up:keys.has('KeyW')||keys.has('ArrowUp'),down:keys.has('KeyS')||keys.has('ArrowDown'),left:keys.has('KeyA')||keys.has('ArrowLeft'),right:keys.has('KeyD')||keys.has('ArrowRight'),clockwise:keys.has('KeyE'),counterclockwise:keys.has('KeyQ'),shoot:keys.has('Space')});accumulator-=1/120;}}else accumulator=0;draw();requestAnimationFrame(frame);}
refreshConfig();view.resize();requestAnimationFrame(frame);
